"""Answer support questions from the shared knowledge index, scoped to the caller."""
from langchain_community.vectorstores import Chroma
from langchain_openai import OpenAIEmbeddings

store = Chroma(collection_name="kb", embedding_function=OpenAIEmbeddings())


def tenant_filter(tenant: str) -> dict:
    """The only supported way to reach the index. Refuses an unscoped read."""
    if not tenant:
        raise ValueError("refusing to query the shared index without a tenant scope")
    return {"tenant_id": tenant}


def build_context(question: str, tenant: str, k: int = 5) -> str:
    docs = store.similarity_search(question, k=k, filter=tenant_filter(tenant))
    return "\n\n".join(d.page_content for d in docs)

